package com.gorillaescape.server.protocol;
import org.junit.jupiter.api.Test;
import java.net.URI;
import java.util.concurrent.atomic.AtomicLong;
import static org.junit.jupiter.api.Assertions.*;
class QaAdmissionTest {
 @Test void expireRegenerateAndPreserveClients(){var clock=new AtomicLong();var s=new TechnicalSession(clock::get,30_000_000_000L,5_000_000_000L,60_000_000_000L);var a=s.createAdmission();var joined=s.join(a.sessionId(),a.token());var q=new QaAdmission();var page=URI.create("https://192.168.1.2:8443/");var first=q.view(s,page,false,true);assertEquals("AVAILABLE",first.state());assertTrue(first.size()<=89);assertFalse(first.toString().contains(a.token()));assertFalse(first.toString().contains("https"));assertEquals(1,s.retainedClients());for(int i=0;i<20;i++)assertEquals("AVAILABLE",q.view(s,page,false,true).state());assertEquals(1,s.retainedClients());clock.set(30_000_000_000L);assertEquals("EXPIRED",q.view(s,page,false,false).state());assertEquals("AVAILABLE",q.view(s,page,false,true).state());assertEquals(joined.playerId(),s.lobby().players().getFirst().playerId());}
 @Test void consumedRevokedAndFull(){var s=new TechnicalSession(System::nanoTime,30_000_000_000L,5_000_000_000L,60_000_000_000L);var a=s.createAdmission();s.revokeAdmission(a.token());assertThrows(IllegalArgumentException.class,()->s.join(a.sessionId(),a.token()));for(int i=0;i<4;i++){var n=s.createAdmission();s.join(n.sessionId(),n.token());}var q=new QaAdmission();assertEquals("SESSION_FULL",q.view(s,URI.create("https://192.168.1.2:8443/"),false,true).state());assertEquals("SESSION_FULL",q.view(s,URI.create("https://192.168.1.2:8443/"),false,false).state());}
 @Test void compactModulesDecodeRealQr()throws Exception {var s=new TechnicalSession(System::nanoTime,30_000_000_000L,5_000_000_000L,60_000_000_000L);var a=s.createAdmission();var uri=JoinQrPoc.link(URI.create("https://192.168.1.2:8443/"),a);var bits=JoinQrPoc.modules(uri);var pure=new com.google.zxing.common.BitMatrix(bits.getWidth()-8);for(int y=4;y<bits.getHeight()-4;y++)for(int x=4;x<bits.getWidth()-4;x++)if(bits.get(x,y))pure.set(x-4,y-4);assertEquals(uri.toString(),new com.google.zxing.qrcode.decoder.Decoder().decode(pure).getText());assertEquals("AVAILABLE",s.admissionState(a));s.join(a.sessionId(),a.token());assertEquals("SCANNED/JOINED",s.admissionState(a));}
}
